        "type": "page",
        "name": "page.tsx",
        "code": "import { UserRolesPage } from \"@/components/openlmis/user-roles-page/user-roles-page\"\n\n// A Next.js App Router route; in any other React app, render UserRolesPage from your own route.\nexport default function Page() {\n  return <UserRolesPage />\n}",
